1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type QuoteResult = { premium: number };
36	export type ClaimResult = { payout: number; remainingCap: number };
37	export type StepResult = QuoteResult | ClaimResult;
38	
39	export interface ScenarioResult {
40	  results: StepResult[];
41	}
42	
43	const PROCESSING_FEE = 5;
44	const FIRST_INSURANCE_SURCHARGE = 0.1;
45	
46	const BASE_PREMIUMS = {
47	  sword: 100,
48	  amulet: 60,
49	  staff: 80,
50	  potion: 40,
51	  rune: 25,
52	  moonstone: 25,
53	} as const satisfies Record<string, number>;
54	
55	type KnownItemType = keyof typeof BASE_PREMIUMS;
56	
57	const isKnownItemType = (itemType: string): itemType is KnownItemType =>
58	  itemType in BASE_PREMIUMS;
59	
60	const basePremiumOf = (itemType: string): number => {
61	  if (!isKnownItemType(itemType)) {
62	    throw new Error(`the MHPCO does not insure items of type "${itemType}"`);
63	  }
64	  return BASE_PREMIUMS[itemType];
65	};
66	
67	const BLOCK_SIZE = 3;
68	const BLOCK_PREMIUM = 60;
69	
70	// Counts occurrences of each item type. The parameter is structural rather
71	// than `Item[]` so callers need only supply the field this actually reads.
72	const countsByType = (typed: { type: string }[]): Map<string, number> => {
73	  const counts = new Map<string, number>();
74	  for (const { type } of typed) counts.set(type, (counts.get(type) ?? 0) + 1);
75	  return counts;
76	};
77	
78	const basePremiumForGroup = (itemType: string, count: number): number => {
79	  if (count === BLOCK_SIZE) return BLOCK_PREMIUM;
80	  return count * basePremiumOf(itemType);
81	};
82	
83	const policyBasePremiumOf = (items: Item[]): number =>
84	  [...countsByType(items)].reduce(
85	    (total, [itemType, count]) => total + basePremiumForGroup(itemType, count),
86	    0,
87	  );
88	
89	const CURSE_SURCHARGE = 0.5;
90	
91	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
92	const HIGH_ENCHANTMENT_THRESHOLD = 5;
93	
94	const itemSurchargeRateOf = (item: Item): number => {
95	  const curse = item.cursed ? CURSE_SURCHARGE : 0;
96	  const enchantment =
97	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD ? HIGH_ENCHANTMENT_SURCHARGE : 0;
98	  return curse + enchantment;
99	};
100	
101	const itemSurchargesOf = (items: Item[]): number =>
102	  items.reduce((total, item) => total + basePremiumOf(item.type) * itemSurchargeRateOf(item), 0);
103	
104	const LOYALTY_DISCOUNT = 0.2;
105	const LOYALTY_THRESHOLD_YEARS = 2;
106	
107	const loyaltyRateOf = (customer: Customer): number =>
108	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS ? -LOYALTY_DISCOUNT : 0;
109	
110	const FOLLOW_UP_DISCOUNT = 0.15;
111	
112	// `contractOrdinal` is zero-based: the customer's first contract in the
113	// scenario is 0 and carries no follow-up discount.
114	const followUpRateOf = (contractOrdinal: number): number =>
115	  contractOrdinal > 0 ? -FOLLOW_UP_DISCOUNT : 0;
116	
117	// The policy-scoped rate is the sum of every modifier that scales the policy
118	// base premium. Each addend names one rule from the spec.
119	const policyModifierRateOf = (customer: Customer, contractOrdinal: number): number =>
120	  FIRST_INSURANCE_SURCHARGE + loyaltyRateOf(customer) + followUpRateOf(contractOrdinal);
121	
122	const premiumFor = (quote: QuoteStep, customer: Customer, contractOrdinal: number): number => {
123	  const policyBase = policyBasePremiumOf(quote.items);
124	  // Policy-scoped modifiers apply to the policy base only; item-scoped
125	  // surcharges are added afterwards and never widen that base.
126	  const policyModifiers = policyBase * policyModifierRateOf(customer, contractOrdinal);
127	  return Math.ceil(
128	    policyBase + itemSurchargesOf(quote.items) + policyModifiers + PROCESSING_FEE,
129	  );
130	};
131	
132	// Every value here is currently 10× the matching base premium, but that is a
133	// coincidence of the current rate card, not a rule the spec states. Deriving
134	// these as `base * 10` would encode the coincidence and have to be undone the
135	// first time one type's insurance value moves independently, so the two tables
136	// stay separate. What they *do* share — the set of insurable types — is
137	// factored out via `KnownItemType` and `isKnownItemType`.
138	const INSURANCE_VALUES = {
139	  sword: 1000,
140	  amulet: 600,
141	  staff: 800,
142	  potion: 400,
143	  rune: 250,
144	  moonstone: 250,
145	} as const satisfies Record<string, number>;
146	
147	// Mirrors `basePremiumOf`: an uninsurable type has no insurance value either.
148	// Unreachable via `runScenario` today — `premiumFor` validates every item type
149	// in a quote before `openPolicy` computes the cap — but the guard keeps the
150	// two lookups honest independently of that call order, and stops an unknown
151	// type from silently reaching the cap arithmetic as `undefined`.
152	const insuranceValueOf = (itemType: string): number => {
153	  if (!isKnownItemType(itemType)) {
154	    throw new Error(`the MHPCO does not insure items of type "${itemType}"`);
155	  }
156	  return INSURANCE_VALUES[itemType];
157	};
158	
159	const DEDUCTIBLE = 100;
160	const CAP_MULTIPLE = 2;
161	
162	interface Policy {
163	  items: Item[];
164	  remainingCap: number;
165	}
166	
167	const openPolicy = (items: Item[]): Policy => {
168	  const insuranceSum = items.reduce((sum, item) => sum + insuranceValueOf(item.type), 0);
169	  return { items, remainingCap: insuranceSum * CAP_MULTIPLE };
170	};
171	
172	const FULL_REIMBURSEMENT = 1;
173	const HALVED_REIMBURSEMENT = 0.5;
174	// Distinct from HIGH_ENCHANTMENT_THRESHOLD (5), which drives the *premium*
175	// surcharge. Enchantment 5–7 costs more to insure but is still reimbursed in
176	// full; only from 8 up is the payout halved.
177	const HALVED_REIMBURSEMENT_THRESHOLD = 8;
178	
179	const reimbursementRateOf = (item: Item): number =>
180	  (item.enchantment ?? 0) >= HALVED_REIMBURSEMENT_THRESHOLD
181	    ? HALVED_REIMBURSEMENT
182	    : FULL_REIMBURSEMENT;
183	
184	// The deductible is withheld once per damage entry, not once per claim.
185	// This is what the entry *earns*, before the policy cap has any say — hence
186	// "owed" rather than "payout", which this codebase reserves for the final
187	// settled figure in `ClaimResult`.
188	const owedForDamage = (damage: Damage, item: Item): number =>
189	  damage.amount * reimbursementRateOf(item) - DEDUCTIBLE;
190	
191	// The insured item a damage entry refers to. The non-null assertion is safe
192	// because `rejectOverclaimedTypes` runs first and rejects any damage type the
193	// policy does not insure in at least the claimed quantity: a type absent from
194	// the policy has an insured count of 0, so any damage naming it is already
195	// rejected as overclaimed. That guard therefore covers both "item not part of
196	// the policy" and "unknown item type" — an unknown type is simply one no
197	// policy can contain. By the time this runs, a match is guaranteed to exist.
198	const insuredItemFor = (damage: Damage, policy: Policy): Item =>
199	  policy.items.find((item) => item.type === damage.itemType)!;
200	
201	const owedForClaim = (claim: ClaimStep, policy: Policy): number =>
202	  claim.incident.damages.reduce(
203	    (total, damage) => total + owedForDamage(damage, insuredItemFor(damage, policy)),
204	    0,
205	  );
206	
207	// Mutates the policy: the cap is drawn down by what was actually paid, so a
208	// later claim against the same policy sees the reduced remainder.
209	const drawDownCap = (policy: Policy, payout: number): number =>
210	  (policy.remainingCap -= payout);
211	
212	// A policy covers a fixed set of items, so a claim may not report more
213	// damages of a type than it insures. The whole claim is rejected.
214	const rejectOverclaimedTypes = (claim: ClaimStep, policy: Policy): void => {
215	  const insuredCounts = countsByType(policy.items);
216	  const claimedCounts = countsByType(
217	    claim.incident.damages.map(({ itemType }) => ({ type: itemType })),
218	  );
219	  for (const [itemType, claimed] of claimedCounts) {
220	    const insured = insuredCounts.get(itemType) ?? 0;
221	    if (claimed > insured) {
222	      throw new Error(
223	        `claim reports ${claimed} ${itemType} damages but the policy insures ${insured}`,
224	      );
225	    }
226	  }
227	};
228	
229	// A damage is an amount of harm suffered; a negative one is nonsense and
230	// would otherwise pay a negative sum and refund the policy's cap.
231	const rejectNegativeAmounts = (claim: ClaimStep): void => {
232	  for (const damage of claim.incident.damages) {
233	    if (damage.amount < 0) {
234	      throw new Error(`damage to a ${damage.itemType} cannot be negative (${damage.amount})`);
235	    }
236	  }
237	};
238	
239	const settleClaim = (claim: ClaimStep, policy: Policy): ClaimResult => {
240	  // Both guards must precede the settling below, and not only to keep the cap
241	  // unmutated on a rejected claim: `insuredItemFor` relies on
242	  // `rejectOverclaimedTypes` having already ruled out damage types the policy
243	  // does not insure. Reordering these would turn a clear error into a crash.
244	  rejectNegativeAmounts(claim);
245	  rejectOverclaimedTypes(claim, policy);
246	  // Rounded down in the MHPCO's favour *before* the draw-down, so the
247	  // remaining cap stays whole. The policy never pays beyond its cap, so a
248	  // claim owed more than the remainder is reduced to it.
249	  const owed = Math.floor(owedForClaim(claim, policy));
250	  const payout = Math.min(owed, policy.remainingCap);
251	  return { payout, remainingCap: drawDownCap(policy, payout) };
252	};
253	
254	export const runScenario = (scenario: Scenario): ScenarioResult => {
255	  // Counts the quote steps seen so far. Only quotes open a contract, so this
256	  // deliberately tracks the customer's contracts rather than the step index —
257	  // a claim step between two quotes must not advance the ordinal.
258	  let contractsSoFar = 0;
259	  const policies = new Map<number, Policy>();
260	
261	  const resultOf = (step: Step, index: number): StepResult => {
262	    if (step.op === "claim") {
263	      const policy = policies.get(step.policy)!;
264	      return settleClaim(step, policy);
265	    }
266	    const premium = premiumFor(step, scenario.customer, contractsSoFar);
267	    contractsSoFar += 1;
268	    policies.set(index, openPolicy(step.items));
269	    return { premium };
270	  };
271	
272	  return { results: scenario.steps.map(resultOf) };
273	};
