3	const readStdin = async (): Promise<string> => {
4	  const chunks: string[] = [];
5	  process.stdin.setEncoding("utf8");
6	  for await (const chunk of process.stdin) chunks.push(chunk);
7	  return chunks.join("");
8	};
9	
10	try {
11	  const scenario = JSON.parse(await readStdin()) as Scenario;
12	  // The results are computed in full before anything is written, so a
13	  // rejected scenario leaves stdout empty rather than half-written.
14	  const results = JSON.stringify(runScenario(scenario));
15	  process.stdout.write(results);
16	} catch (error) {
17	  process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
18	  process.exit(1);
19	}
