11	const runCli = (input: string): Promise<CliRun> =>
12	  new Promise((resolve, reject) => {
13	    const child = spawn("node_modules/.bin/tsx", ["src/cli.ts"], { stdio: "pipe" });
14	    let stdout = "";
15	    let stderr = "";
16	    child.stdout.on("data", (chunk) => (stdout += chunk));
17	    child.stderr.on("data", (chunk) => (stderr += chunk));
18	    child.on("error", reject);
19	    child.on("close", (code) => resolve({ code: code ?? 0, stdout, stderr }));
20	    child.stdin.end(input);
21	  });
